"""
test_stubs.py
Suggested test stubs for high-risk modules that have none.

Milestone 5.2. A module in the blast radius with no test file is a
regression waiting to happen. The generator produces a starting point.

**It is always a SUGGESTION.** The output is labelled "generated by AI
— review before committing", and nothing here ever writes a file into
the repository. A bot that commits generated tests is a bot that commits
bugs.

The generation goes through `runtime_config.ask_llm` and is parsed with
`backend/json_utils.py`, which is already hardened for the broken JSON
that models produce. A malformed response yields a clear error, not a
traceback.
"""
from __future__ import annotations

import json
import logging
import re
from pathlib import Path

from json_utils import extract_json_object

log = logging.getLogger("reposcope.test_stubs")

#: The marker every generated stub carries. It must be impossible to
#: mistake generated code for reviewed code.
GENERATED_MARKER = "generated by AI — review before committing"

#: The system prompt. It asks for ONE test file, in the repository's
#: own conventions.
STUB_SYSTEM_PROMPT = (
    "You write minimal pytest test stubs for untested modules.\n"
    "Rules:\n"
    "1. Return ONLY a JSON object with the keys 'filename' and 'code'.\n"
    "2. 'filename' is the test file path (e.g. 'tests/test_auth.py').\n"
    "3. 'code' is a complete, runnable pytest file.\n"
    "4. Test the OBSERVABLE behaviour of the module, not its internals.\n"
    "5. Do not invent behaviour. If a function's purpose is unclear, "
    "write a test that asserts it raises rather than guessing its result.\n"
    "6. Keep it under 60 lines."
)


def find_untested_modules(
    graph: dict,
    changed_files: list[str],
    tests_present: list[str] | None = None,
) -> list[str]:
    """
    The changed modules that no test file covers.

    A module counts as covered when a test file mentions its name.
    """
    modules = [f for f in changed_files if f and not _looks_like_test(f)]
    if not modules:
        return []

    haystack = "\n".join(tests_present or []).lower()
    untested: list[str] = []
    for module in modules:
        stem = Path(module).stem.lower()
        if stem and stem in haystack:
            continue
        untested.append(module)
    return untested


def _looks_like_test(path: str) -> bool:
    lowered = path.lower()
    name = Path(lowered).name
    return (
        name.startswith("test_")
        or name.endswith("_test.py")
        or name.endswith(".test.ts")
        or name.endswith(".test.js")
        or name.endswith(".spec.ts")
        or "/tests/" in lowered
        or "/test/" in lowered
        or lowered.endswith("test.py")
    )


async def generate_stub(
    module_path: str,
    module_source: str,
    provider: dict | None = None,
) -> dict:
    """
    Generate a test stub for one module.

    Returns `{"ok": True, "filename", "code", "module"}` or
    `{"ok": False, "error"}`. It never raises: a failed generation is a
    result, not an exception.
    """
    from runtime_config import ask_llm

    prompt = (
        f"Module: {module_path}\n\n"
        f"Source:\n```\n{module_source[:6000]}\n```\n\n"
        "Write a pytest file that tests this module's public behaviour."
    )

    try:
        raw = await ask_llm(
            STUB_SYSTEM_PROMPT, prompt, provider=provider,
        )
    except Exception as exc:  # noqa: BLE001 - a failed generation is a result
        log.warning("Test-stub generation failed for %s: %s", module_path, exc)
        return {"ok": False, "module": module_path, "error": str(exc)}

    payload = extract_json_object(raw)
    if not payload:
        return {
            "ok": False,
            "module": module_path,
            "error": "The model did not return usable JSON.",
        }

    filename = str(payload.get("filename") or "").strip()
    code = str(payload.get("code") or "").strip()
    if not filename or not code:
        return {
            "ok": False,
            "module": module_path,
            "error": "The model's reply was missing the filename or the code.",
        }

    if not filename.endswith(".py"):
        filename = filename if filename.endswith(".py") else f"{filename}.py"

    return {
        "ok": True,
        "module": module_path,
        "filename": filename,
        "code": _mark_generated(code),
        "note": GENERATED_MARKER,
    }


def _mark_generated(code: str) -> str:
    """Put the marker at the top of the file, where it cannot be missed."""
    banner = (
        f"# {GENERATED_MARKER}\n"
        f"#\n"
        f"# This is a SUGGESTION. Review it before committing.\n\n"
    )
    if GENERATED_MARKER in code:
        return code
    return banner + code


def render_stub_suggestion(stub: dict) -> str:
    """A stub, rendered for the PR comment."""
    if not stub.get("ok"):
        return ""
    return (
        f"**Suggested test: `{stub['filename']}`** for `{stub['module']}`\n\n"
        f"> ⚠️ *{GENERATED_MARKER}*\n\n"
        f"```python\n{stub['code']}\n```\n"
    )
